def tokenize(expr: str):
    # Regex to match numbers (int/float), operators, parens, and ignore whitespace
    pattern = r'\s*(\d+\.?\d*|\.\d+|[+\-*/()]|\S+)\s*'
    tokens = re.findall(pattern, expr)
    result = []
    for t in tokens:
        if t.lstrip().rstrip():  # Skip pure whitespace (though regex should handle it)
            # Check if it's a number
            try:
                result.append(float(t))
            except ValueError:
                result.append(t)
    return result

def parse_expression(tokens, pos):
    # For now, just parse a single number
    if pos[0] >= len(tokens):
        raise ExpressionError("Unexpected end of expression")

    token = tokens[pos[0]]
    if isinstance(token, float):
        pos[0] += 1
        return token, pos[0]
    else:
        raise ExpressionError(f"Expected number, got {token}")
